INSERT INTO `song` VALUES (1,'晴天','周杰伦','http://10.0.2.2:8080/music/test.mp3','http://localhost:8080/image/test.png','http://localhost:8080/lyric/test.lrc',NULL,NULL),(26743,'Empty','Tryad','https://prod-1.storage.jamendo.com/?trackid=26743&format=mp32&from=51KZExsyuRFZ61OxBDktcw%3D%3D%7CFLb6qsjLbbQFoQDzNlsDgQ%3D%3D','https://usercontent.jamendo.com?type=album&id=3661&width=300&trackid=26743',NULL,'JAMENDO','do what you will\r\nshare some sympathy\r\nall that you do with me\r\nis lost in eternity\r\n\r\ngrab all you want\r\nyou\'ll never hold on to me\r\neverything you see\r\nis totally empty\r\n\r\nnothing we feel\r\nis lasting or real\r\neverything fades\r\nwomb to the grave\r\n\r\ntake what you can\r\nyet in the end\r\nit\'s all nowhere\r\nsmoke in thin air\r\n\r\ncome what may\r\nall i can say\r\nis savor this day\r\nit will pass away\r\n\r\nif everyone knew\r\ntheir years are few\r\nwhat would they do\r\nfaced with this truth\r\n\r\nso here we all are\r\nworking so hard\r\nclimbing so high\r\ndo we know why\r\n\r\none thing is clear\r\neveryone here\r\nis in the same boat\r\nsink or float\r\n\r\nlive and learn\r\nsuddenly turns\r\nto one more step\r\ndie and forget'),(26744,'Mesmerize','Tryad','https://prod-1.storage.jamendo.com/?trackid=26744&format=mp32&from=uaYHmyvGZR8WR3VKPSIYCg%3D%3D%7CUBJlozVKPt0UuY5RtaLQJA%3D%3D','https://usercontent.jamendo.com?type=album&id=3661&width=300&trackid=26744',NULL,'JAMENDO','when there\'s no place you feel at home\r\nand you think you\'d be better off alone\r\n\r\nwhen you think there\'s no reason to try\r\nand you hate yourself and you wanna die\r\n\r\nwhen you\'re filled with anxiety\r\neveryone\'s your enemy\r\nwanna go out and kill yourself\r\n\r\nyou\'re overreacting\r\n\r\ndepressed\r\nbecause you think you can\'t do your best\r\n\r\nwhen you write yourself a stupid song\r\nto remind yourself that you forgot\r\n\r\nyou\'re overreacting'),(26745,'All the Same','Tryad','https://prod-1.storage.jamendo.com/?trackid=26745&format=mp32&from=72KE2Qy6qtoAnFcTKzDpXg%3D%3D%7CHl7ttXJdMajbFM86e1IN%2BQ%3D%3D','https://usercontent.jamendo.com?type=album&id=3661&width=300&trackid=26745',NULL,'JAMENDO','dream\r\nin a dream\r\n\r\nsunlight\r\nin the darkness\r\n\r\nsound\r\nin the silence\r\n\r\nwhisper\r\nin a crowd\r\n\r\noh i, separate it\r\noh i, liberate it\r\n\r\nit\'s all a dream to me\r\nit\'s all the same to me\r\n\r\ni wonder\r\nwhile I wait\r\n\r\ni think\r\nanticipate\r\n\r\ni kiss\r\nyour lips\r\nyour spirit\r\n\r\noh i, separate it\r\n\r\noh i, separate it\r\noh i, liberate it\r\n\r\nit\'s all the same\r\nit\'s all a dream\r\nto dream'),(26746,'This','Tryad','https://prod-1.storage.jamendo.com/?trackid=26746&format=mp32&from=Ot7VqlXp9SFl9UbhxE8kJw%3D%3D%7C2eUwdaq6ynKNRkX57cU%2BUg%3D%3D','https://usercontent.jamendo.com?type=album&id=3661&width=300&trackid=26746',NULL,'JAMENDO','this\r\nthis is the way\r\nhow we move through the rain\r\nhow we grow through the pain\r\ninto the day\r\nof youth born again\r\n\r\nthis\r\nthis is the place\r\nwhere we open up our minds\r\nwhere we turn and raise our eyes\r\ninto the space\r\nof limitless faith\r\n\r\nthis is everything\r\n\r\nthis\r\nthis is the time\r\nwhere we find we\'ve got enough\r\nwhere everyone all gives up\r\ninto the light\r\nof universal love\r\n\r\nthis\r\nthis is home\r\nwhere you and i both come from\r\nwhere we are forever one\r\nwithin this sea\r\nof tranquility\r\n\r\nthis is everything\r\n\r\nthis\r\nthis is the end\r\nwhere nothing else can be said\r\nwhere words can no longer tread\r\nonward we go\r\nbeyond the known'),(26748,'Far and Away','Tryad','https://prod-1.storage.jamendo.com/?trackid=26748&format=mp32&from=GrvedrOuuvoRCA2iloMmTw%3D%3D%7CTbQK199ElJHJ2bwhx60ApA%3D%3D','https://usercontent.jamendo.com?type=album&id=3661&width=300&trackid=26748',NULL,'JAMENDO',NULL),(469574,'Alone Tonight','Leslie Hunt','https://prod-1.storage.jamendo.com/?trackid=469574&format=mp32&from=qK2cdAZ7cy84H08jTG2Bpw%3D%3D%7CFQcs0xneE5dHFTBm5UKNog%3D%3D','https://usercontent.jamendo.com?type=album&id=55594&width=300&trackid=469574',NULL,'JAMENDO',NULL),(525912,'A Higher Loss','Emerald Park','https://prod-1.storage.jamendo.com/?trackid=525912&format=mp32&from=py5aqkbzxDwsW4FSdndSAQ%3D%3D%7CaLCJ%2B%2FdOp77nADIQOJUAHg%3D%3D','https://usercontent.jamendo.com?type=album&id=61436&width=300&trackid=525912',NULL,'JAMENDO','She never said: \r\n”Why, didn’t you give me a chance, \r\nA chance to sort things out before you left me?”\r\nI wanted to leave\r\nTo leave her with pain. \r\nWith an ache inside \r\nHer heart since I left her.\r\nThe regret that I feel \r\nis honest and real\r\nThere’s an ache inside my heart \r\nsince I left her\r\n\r\nI jumped into conclusions\r\nA leap out of her shiny, tiny world\r\nA big misunderstanding\r\nI thought there was more than us\r\nIt’s a higher loss than I ever thought it was\r\n\r\nShe never denied\r\nNo she never really tried\r\nTo explain the circumstances\r\nSo I left her\r\n\r\nI jumped into conclusions\r\nA leap out of her shiny, tiny world\r\nA big misunderstanding\r\nI thought there was more than us\r\nIt’s a higher loss than I ever thought it was'),(525914,'Istanbul','Emerald Park','https://prod-1.storage.jamendo.com/?trackid=525914&format=mp32&from=qdTtRXiW%2FKK5%2FaTo9j7a1g%3D%3D%7CHmUGZe3AnrE5Pjr6gqdw%2BQ%3D%3D','https://usercontent.jamendo.com?type=album&id=61436&width=300&trackid=525914',NULL,'JAMENDO','I’m sorry\r\nYou found out\r\nI didn’t enjoy\r\nI didn’t approve\r\nThat you called me\r\nAnd told me\r\nI were not to blame\r\nIt feels quite insane\r\n\r\nBut now you’ve heard me\r\nI’ve hurt thee\r\nCreature inside\r\nThe living in life\r\nNow it’s your turn\r\nAnd my concern\r\nYou aren’t to blame\r\nIt feels quite insane\r\n\r\nLet’s use the fire to burn down the shaft\r\nLet’s use the fire to burn down the shaft\r\nUse the fire to burn it down\r\nThe half builded fake walls\r\nIstanbul is crumbling\r\nSo lets burn!'),(553676,'Boy','The Different','https://prod-1.storage.jamendo.com/?trackid=553676&format=mp32&from=ff5qht1FJM2wtlG65WzolQ%3D%3D%7CBRQ1ZL9wk0293NUyKJPgNw%3D%3D','https://usercontent.jamendo.com?type=album&id=64407&width=300&trackid=553676',NULL,'JAMENDO',NULL),(682351,'Moon & Sun - Salt & Indigo','Moon & Sun','https://prod-1.storage.jamendo.com/?trackid=682351&format=mp32&from=e%2BQJD78P10xcNAFunZSiUQ%3D%3D%7CA%2Ft2Ea2DGls8A%2FLaP3H%2BZg%3D%3D','https://usercontent.jamendo.com?type=album&id=79335&width=300&trackid=682351',NULL,'JAMENDO',NULL),(724513,'Tonight','Olga Zhilkova','https://prod-1.storage.jamendo.com/?trackid=724513&format=mp32&from=fjm%2Fk0GKYXHt4LzRtHfMlw%3D%3D%7C%2Fuy1svTGrUUBGZugYXcznw%3D%3D','https://usercontent.jamendo.com?type=album&id=84637&width=300&trackid=724513',NULL,'JAMENDO',NULL),(989175,'The Highlights','Sunwill','https://prod-1.storage.jamendo.com/?trackid=989175&format=mp32&from=VwumAyc5AFYqsRsVBwpZ6w%3D%3D%7CIXyMQ7jcwQXH6Sfi3WnDkQ%3D%3D','https://usercontent.jamendo.com?type=album&id=116379&width=300&trackid=989175',NULL,'JAMENDO',NULL),(1045016,'Don\'t Lose Your Way','Olga Zhilkova','https://prod-1.storage.jamendo.com/?trackid=1045016&format=mp32&from=MfZpVH%2FUP5E9uThGaXahSA%3D%3D%7C6gaCbAUN6Pbi7FmDdQlQmA%3D%3D','https://usercontent.jamendo.com?type=album&id=123064&width=300&trackid=1045016',NULL,'JAMENDO',NULL),(1093795,'Reach the Stars','JekK','https://prod-1.storage.jamendo.com/?trackid=1093795&format=mp32&from=cV%2BSI%2BOwP%2BGf66iiVhXxKQ%3D%3D%7C8JrBgB%2BibEYgriERNSsZTw%3D%3D','https://usercontent.jamendo.com?type=album&id=130370&width=300&trackid=1093795',NULL,'JAMENDO',NULL),(1119655,'The Limit','Robert Avellanet','https://prod-1.storage.jamendo.com/?trackid=1119655&format=mp32&from=6bQJ8VgqTKoMP3wzvONlmg%3D%3D%7CCq8Pb0nI38lWiCQfPWDEjQ%3D%3D','https://usercontent.jamendo.com?type=album&id=133798&width=300&trackid=1119655',NULL,'JAMENDO',NULL),(1119656,'Love Will Break the Walls','Robert Avellanet','https://prod-1.storage.jamendo.com/?trackid=1119656&format=mp32&from=Dwj5FMwd6BV0ahkq78MLJA%3D%3D%7C16hz9V6JiZgNtdaKITxnrQ%3D%3D','https://usercontent.jamendo.com?type=album&id=133798&width=300&trackid=1119656',NULL,'JAMENDO',NULL),(1174818,'Ghost','madelyn munsell','https://prod-1.storage.jamendo.com/?trackid=1174818&format=mp32&from=%2BpD9OMgRH6lsWaH5WNd6bA%3D%3D%7CwvIyiHQvVK0%2FRhR9o1qM2A%3D%3D','https://usercontent.jamendo.com?type=album&id=141498&width=300&trackid=1174818',NULL,'JAMENDO','do you remember that first time you felt alive?\r\nlaying on your roof in the summer, staring at the sky \r\nin your living room, slow dance on new years eve, \r\ntoo young to notice, too young to think \r\nyou\'re a ghost to me \r\ndoes she make you feel alive \r\nlike your world is set on fire \r\nand nothing can stop you here tonight \r\nis she the one that tells you everything is fine \r\nwhen it\'s not \r\nand does try to heal the sickness in your eyes? \r\nthat\'s what i thought \r\nyou\'re a ghost to me \r\ni\'m sick and tired of being tired and sick \r\ni can\'t make you love what you haven\'t missed. \r\nyour heart\'s a clock and that is it. \r\n\r\nwhen did the fire leave my bones? \r\nwhen did the fire leave your eyes?'),(1209658,'Flying Over The Golden Peaks','Matti Paalanen','https://prod-1.storage.jamendo.com/?trackid=1209658&format=mp32&from=Blpr8hhHWF7RKV2mU%2BDSGw%3D%3D%7CvxaMFBERE5h60pwB3xKsqA%3D%3D','https://usercontent.jamendo.com?type=album&id=145266&width=300&trackid=1209658',NULL,'JAMENDO',NULL),(1214592,'She Knows','JARA','https://prod-1.storage.jamendo.com/?trackid=1214592&format=mp32&from=GHEUUdZJhfsjh9KdTkcZAw%3D%3D%7CJEsyWnEbmO8Rw1%2FuB8QWMg%3D%3D','https://usercontent.jamendo.com?type=album&id=145734&width=300&trackid=1214592',NULL,'JAMENDO',NULL),(1334054,'Fallen Star','AJC &amp; The Envelope Pushers','https://prod-1.storage.jamendo.com/?trackid=1334054&format=mp32&from=nCCBAj8tINCXwcez0tB%2B1A%3D%3D%7C0Sf3fDzk2KAyVOEklyaWkg%3D%3D','https://usercontent.jamendo.com?type=album&id=157742&width=300&trackid=133405